func TestExpandPath(t *testing.T) {
	if got := ExpandPath("~/dotfiles/bashrc", "/home/u"); got != "/home/u/dotfiles/bashrc" {
		t.Fatalf("ExpandPath = %q", got)
	}
	if got := ExpandPath("/abs/file", "/home/u"); got != "/abs/file" {
		t.Fatalf("ExpandPath = %q", got)
	}
}

func TestUnifiedDiff(t *testing.T) {
	oldText := "a\nb\nc\n"
	newText := "a\nB\nc\n"
	diff := UnifiedDiff(oldText, newText, "bash (live)", "bash (pending)")
	for _, want := range []string{"--- bash (live)\n", "+++ bash (pending)\n", "@@ -1,3 +1,3 @@\n", " a\n", "-b\n", "+B\n", " c\n"} {
		if !strings.Contains(diff, want) {
			t.Errorf("diff is missing %q:\n%s", want, diff)
		}
	}
	if UnifiedDiff(oldText, oldText, "a", "b") != "" {
		t.Fatal("identical inputs produced a diff")
	}
}

func TestUnifiedDiffInsertAndDelete(t *testing.T) {
	diff := UnifiedDiff("one\ntwo\n", "zero\none\ntwo\nthree\n", "old", "new")
	for _, want := range []string{"+zero\n", "+three\n", "@@"} {
		if !strings.Contains(diff, want) {
			t.Errorf("diff is missing %q:\n%s", want, diff)
		}
	}
	diff = UnifiedDiff("zero\none\ntwo\nthree\n", "one\ntwo\n", "old", "new")
	for _, want := range []string{"-zero\n", "-three\n", "@@"} {
		if !strings.Contains(diff, want) {
			t.Errorf("reverse diff is missing %q:\n%s", want, diff)
		}
	}
}

func TestDisplayLineEscapesLayout(t *testing.T) {
	got := DisplayLine("one\ntwo\tthree\r")
	if strings.ContainsAny(got, "\n\t\r") {
		t.Fatalf("layout characters survived DisplayLine: %q", got)
	}
	if !strings.Contains(got, `\n`) || !strings.Contains(got, `\t`) || !strings.Contains(got, `\r`) {
		t.Fatalf("layout characters were not made visible: %q", got)
	}
	if !strings.Contains(DisplaySafe("one\ntwo"), "\n") {
		t.Fatal("DisplaySafe should preserve diff layout")
	}
}

func TestUnifiedDiffEscapesControlCharacters(t *testing.T) {
	diff := UnifiedDiff("old\n", "echo \x1b[31mred\n", "old", "new")
	if strings.ContainsRune(diff, '\x1b') {
		t.Fatalf("raw escape character reached the diff:\n%q", diff)
	}
	if !strings.Contains(diff, `\u001B`) {
		t.Fatalf("escape character was not made visible:\n%s", diff)
	}
}

func TestProfilePathFallback(t *testing.T) {
	t.Setenv("PATH", t.TempDir())
	got, err := ProfilePath(context.Background(), ShellPwsh, "/home/u")
	if err != nil {
		t.Fatalf("ProfilePath: %v", err)
	}
	if !strings.Contains(got, "Microsoft.PowerShell_profile.ps1") {
		t.Fatalf("unexpected profile path %q", got)
	}
	if _, err := ProfilePath(context.Background(), ShellBash, ""); err == nil {
		t.Fatal("expected an error without a home directory")
	}
	got, err = ProfilePath(context.Background(), ShellPowerShell, "/home/u")
	if err != nil || !strings.Contains(got, "Microsoft.PowerShell_profile.ps1") {
		t.Fatalf("powershell fallback = %q, %v", got, err)
	}
}

func TestProfilePathUsesPwsh(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("fake pwsh script uses a POSIX shebang")
	}
	dir := t.TempDir()
	pwsh := filepath.Join(dir, "pwsh")
	if err := os.WriteFile(pwsh, []byte("#!/bin/sh\nprintf '/custom/profile.ps1\\n'\n"), 0o755); err != nil {
		t.Fatal(err)
	}
	t.Setenv("PATH", dir)
	got, err := ProfilePath(context.Background(), ShellPwsh, "/home/u")
	if err != nil {
		t.Fatalf("ProfilePath: %v", err)
	}
	if got != "/custom/profile.ps1" {
		t.Fatalf("ProfilePath = %q", got)
	}
}

func TestProfilePathPrefersRequestedPowerShell(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("fake scripts use a POSIX shebang")
	}
	dir := t.TempDir()
	writeScript := func(name, body string) {
		path := filepath.Join(dir, name)
		if err := os.WriteFile(path, []byte("#!/bin/sh\n"+body+"\n"), 0o755); err != nil {
			t.Fatal(err)
		}
	}
	writeScript("pwsh", "printf '/pwsh.ps1\\n'")
	writeScript("powershell", "printf '/ps5.ps1\\n'")
	t.Setenv("PATH", dir)

	if got, _ := ProfilePath(context.Background(), ShellPowerShell, "/home/u"); got != "/ps5.ps1" {
		t.Fatalf("powershell profile = %q", got)
	}
	if got, _ := ProfilePath(context.Background(), ShellPwsh, "/home/u"); got != "/pwsh.ps1" {
		t.Fatalf("pwsh profile = %q", got)
	}

	// A failed query for the requested shell must not silently select the
	// other executable's profile.
	writeScript("powershell", "exit 1")
	if got, _ := ProfilePath(context.Background(), ShellPowerShell, "/home/u"); got == "/pwsh.ps1" {
		t.Fatalf("failed query fell through to the wrong profile: %q", got)
	}
}

func TestUnifiedDiffManyLines(t *testing.T) {
	var oldB, newB strings.Builder
	for i := 0; i < 500; i++ {
		oldB.WriteString("same\n")
		newB.WriteString("same\n")
	}
	oldB.WriteString("old\n")
	newB.WriteString("new\n")
	diff := UnifiedDiff(oldB.String(), newB.String(), "old", "new")
	if !strings.Contains(diff, "-old\n") || !strings.Contains(diff, "+new\n") {
		t.Fatalf("large diff was not produced:\n%s", diff)
	}
}

func TestParsedShell(t *testing.T) {
	for in, want := range map[string]Shell{"bash": ShellBash, "zsh": ShellZsh, "pwsh": ShellPwsh, "powershell": ShellPowerShell} {
		got, err := ParsedShell(in)
		if err != nil || got != want {
			t.Errorf("ParsedShell(%q) = %q, %v", in, got, err)
		}
	}
	if _, err := ParsedShell("fish"); err == nil {
		t.Error("fish should not be accepted yet")
	}
	if _, err := ParsedShell("cmd"); err == nil {
		t.Error("cmd should not be accepted")
	}
}
